// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.ocrimport android.graphics.Bitmap/** * Convert an [RgbImage] to an Android [Bitmap]. * * The resulting Bitmap is in `ARGB_8888` format and can be passed directly * to ML Kit's [InputImage.fromBitmap]. * * Performance: O(N) where N = width × height. For a 320×240 frame this is * ~77k pixels — well under 5 ms on Helio G85. * * Caller is responsible for calling [Bitmap.recycle] when done with the * bitmap (or for one-shot ML Kit calls, the GC will handle it). */fun RgbImage.toBitmap(): Bitmap {    val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)    val n = width * height    val pixels = IntArray(n)    val src = this.pixels    var srcIdx = 0    var dstIdx = 0    while (dstIdx < n) {        // Pack RGB (3 bytes) into ARGB int (0xFF alpha).        val r = src[srcIdx].toInt() and 0xFF        val g = src[srcIdx + 1].toInt() and 0xFF        val b = src[srcIdx + 2].toInt() and 0xFF        pixels[dstIdx] = (0xFF shl 24) or (r shl 16) or (g shl 8) or b        srcIdx += 3        dstIdx++    }    bitmap.setPixels(pixels, 0, width, 0, 0, width, height)    return bitmap}/** * Convert a [GrayscaleImage] to an Android [Bitmap]. * * The resulting Bitmap is in `ARGB_8888` format with R=G=B=gray. */fun GrayscaleImage.toBitmap(): Bitmap {    val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)    val n = width * height    val pixels = IntArray(n)    val src = this.pixels    for (i in 0 until n) {        val g = src[i].toInt() and 0xFF        // Pack gray into ARGB (R=G=B=gray, A=255).        pixels[i] = (0xFF shl 24) or (g shl 16) or (g shl 8) or g    }    bitmap.setPixels(pixels, 0, width, 0, 0, width, height)    return bitmap}